with u0 as (update public.questions set body='Consider the following statements regarding the Central Bureau of Investigation (CBI):', question_data='{"statements": ["The CBI derives its power to investigate from the Delhi Special Police Establishment Act, 1946.", "The Director of the CBI is appointed on the recommendation of a committee chaired by the Prime Minister."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb, options='[{"id": "a", "body": "1 only", "isCorrect": false}, {"id": "b", "body": "2 only", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "isCorrect": false}]'::jsonb, explanation='Both statements are correct. The CBI''s legal basis for investigation is the Delhi Special Police Establishment Act, 1946. Since the Lokpal and Lokayuktas Act, 2013 amended the DSPE Act, the Director is appointed on the recommendation of a committee of the Prime Minister (Chairperson), the Leader of the Opposition or leader of the single largest opposition party in the Lok Sabha, and the Chief Justice of India or a Supreme Court judge nominated by the CJI. Readers relying on older notes may wrongly reject statement 2: before 2014 the committee was chaired by the Central Vigilance Commissioner.' where exam_category='upsc' and subject='Polity' and concept_group_id='governance-cbi-dspe-director-appointment' returning concept_group_id), u1 as (update public.questions set body='Consider the following statements regarding inter-State river water disputes:', question_data='{"statements": ["Under Article 262, Parliament may by law provide that neither the Supreme Court nor any other court shall exercise jurisdiction over such disputes.", "Water disputes tribunals under the Inter-State River Water Disputes Act, 1956 are constituted by the Central Government.", "The decision of a water disputes tribunal under the Act has the same force as an order or decree of the Supreme Court."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb, options='[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "All three", "isCorrect": true}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb, explanation='All three statements are correct. Art. 262(2) allows Parliament to exclude the jurisdiction of all courts, including the Supreme Court, over such disputes; under the Inter-State River Water Disputes Act, 1956 the Central Government constitutes a tribunal when a dispute cannot be settled by negotiation; and Section 6(2) of the Act (inserted in 2002) gives a tribunal''s decision the same force as an order or decree of the Supreme Court. The tempting error is to assume that the Supreme Court sets up the tribunals.' where exam_category='upsc' and subject='Polity' and concept_group_id='federalism-inter-state-water-disputes-art262' returning concept_group_id), u2 as (update public.questions set body='Consider the following statements regarding the Citizenship (Amendment) Act, 2019:', question_data='{"statements": ["It makes persons belonging to the Hindu, Sikh, Buddhist, Jain, Parsi and Christian communities from Afghanistan, Bangladesh and Pakistan eligible for citizenship.", "To be eligible under the Act, such persons must have entered India on or before 31 December 2016.", "It reduced the period of residence required for naturalisation of such persons from eleven years to seven years."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb, options='[{"id": "a", "body": "Only one", "isCorrect": true}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb, explanation='Only statement 1 is correct: the Act covers these six communities from the three countries. Statement 2 changes the cut-off date: the Act applies to those who entered India on or before 31 December 2014. Statement 3 changes the number: the naturalisation residence requirement for them was reduced from eleven years to five years, not seven. The Citizenship (Amendment) Rules were notified in March 2024. The Act also does not apply to the Sixth Schedule tribal areas of Assam, Meghalaya, Mizoram and Tripura, or to areas under the Inner Line Permit.' where exam_category='upsc' and subject='Polity' and concept_group_id='polity-caa-2019-cutoff-naturalisation' returning concept_group_id), u3 as (update public.questions set body='Consider the following statements regarding the Department-related Standing Committees (DRSCs) of Parliament:', question_data='{"statements": ["There are 24 DRSCs, of which 16 function under the Lok Sabha and 8 under the Rajya Sabha.", "Each DRSC consists of 31 members: 21 from the Lok Sabha and 10 from the Rajya Sabha.", "The Chairperson of every DRSC is appointed by the Speaker of the Lok Sabha.", "The recommendations of the DRSCs on the demands for grants are binding on the Government."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb, options='[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "Only three", "isCorrect": false}, {"id": "d", "body": "All four", "isCorrect": false}]'::jsonb, explanation='Statements 1 and 2 are correct: the system set up in 1993 was expanded in 2004 to 24 committees (16 serviced by the Lok Sabha and 8 by the Rajya Sabha), each with 31 members (21 + 10); ministers cannot be members. Statement 3 is incorrect: the Speaker appoints the Chairpersons of the 16 Lok Sabha committees, but the Chairpersons of the 8 Rajya Sabha committees are appointed by the Chairman of the Rajya Sabha. Statement 4 is incorrect: DRSC reports are advisory and do not bind the Government.' where exam_category='upsc' and subject='Polity' and concept_group_id='polity-department-related-standing-committees' returning concept_group_id), u4 as (update public.questions set body='Consider the following statements regarding the Public Examinations (Prevention of Unfair Means) Act, 2024:', question_data='{"statements": ["Offences under the Act are bailable and can be compounded with the consent of the examination authority.", "It covers public examinations conducted by bodies such as the Union Public Service Commission, the Staff Selection Commission and the National Testing Agency.", "It applies directly to the recruitment examinations conducted by the State Public Service Commissions."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb, options='[{"id": "a", "body": "Only one", "isCorrect": true}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb, explanation='Only statement 2 is correct: the Act applies to the public examination authorities listed in its Schedule, including UPSC, SSC, the Railway Recruitment Boards, IBPS and NTA, as well as central ministries and departments. Statement 1 is incorrect: every offence under the Act is cognizable, non-bailable and non-compoundable. Statement 3 is incorrect: the Act applies to central examinations; State examinations are outside it unless a State adopts it or enacts its own law.' where exam_category='upsc' and subject='Polity' and concept_group_id='statute-public-examinations-act-2024' returning concept_group_id), u5 as (update public.questions set body='Consider the following statements regarding the Prime Minister of India:', question_data='{"statements": ["The Constitution lays down a specific procedure for the selection and appointment of the Prime Minister.", "A person must be a member of the Lok Sabha at the time of appointment as Prime Minister."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb, options='[{"id": "a", "body": "1 only", "isCorrect": false}, {"id": "b", "body": "2 only", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "isCorrect": true}]'::jsonb, explanation='Neither statement is correct. Statement 1 is incorrect: Art. 75 merely says the Prime Minister shall be appointed by the President and lays down no procedure for the selection; by convention the President appoints the leader of the majority party or coalition in the Lok Sabha. Statement 2 is incorrect: a member of either House -- or even a non-member, who must then become a member of either House within six months -- can be appointed; several Prime Ministers have been members of the Rajya Sabha.' where exam_category='upsc' and subject='Polity' and concept_group_id='executive-prime-minister-appointment' returning concept_group_id), u6 as (update public.questions set body='Consider the following statements regarding the Vice-President of India:', question_data='{"statements": ["The Vice-President is elected by an electoral college consisting of the members of both Houses of Parliament.", "As in the Presidential election, the elected members of the State Legislative Assemblies also vote in the election of the Vice-President.", "A formal impeachment is not required for the removal of the Vice-President.", "The Vice-President elected in September 2025 after a mid-term vacancy holds office only for the remainder of the predecessor''s term."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb, options='[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "Only three", "isCorrect": false}, {"id": "d", "body": "All four", "isCorrect": false}]'::jsonb, explanation='Statements 1 and 3 are correct: the electoral college under Art. 66 comprises all members, elected and nominated, of both Houses of Parliament, and under Art. 67(b) the Vice-President is removed by a Rajya Sabha resolution passed by a majority of all its then members and agreed to by the Lok Sabha -- no impeachment is needed. Statement 2 is incorrect: unlike the Presidential electoral college, the Vice-Presidential one includes no members of the State Legislative Assemblies. Statement 4 is incorrect: under Art. 68(2), a person elected to fill a vacancy caused by resignation holds office for a full term of five years from the date of entering office; C.P. Radhakrishnan, elected on 9 September 2025, therefore has a full five-year term.' where exam_category='upsc' and subject='Polity' and concept_group_id='executive-vice-president-election-term' returning concept_group_id)
select count(*) as updated from (select * from u0 union all select * from u1 union all select * from u2 union all select * from u3 union all select * from u4 union all select * from u5 union all select * from u6) x;
